  box(-1.15,1.67,.02,.15,3.35,.35,mats.trim,doorGroup);box(1.15,1.67,.02,.15,3.35,.35,mats.trim,doorGroup);box(0,3.36,.02,2.4,.2,.35,mats.trim,doorGroup);
  door=mesh(new THREE.BoxGeometry(2.13,3.12,.16),mats.door,0,1.58,.13,doorGroup);
  door.userData.interactive='door';door.rotation.y=0;
  box(-.88,1.58,.23,.08,2.9,.05,mats.trim,doorGroup);box(.88,1.58,.23,.08,2.9,.05,mats.trim,doorGroup);box(0,2.97,.23,1.76,.08,.05,mats.trim,doorGroup);box(0,.2,.23,1.76,.08,.05,mats.trim,doorGroup);
  const knob=mesh(new THREE.SphereGeometry(.075,12,8),mats.metal,.77,1.38,.26,doorGroup);
  const plaqueMat=new THREE.MeshStandardMaterial({color:0x70552f,metalness:.6,roughness:.45});box(0,2.55,.24,.45,.28,.05,plaqueMat,doorGroup);
  const letters=new THREE.MeshStandardMaterial({color:0x17120d,emissive:0x090604});mesh(new THREE.BoxGeometry(.23,.045,.01),letters,0,2.55,.27,doorGroup);
